window.SPATAIL_LAB_EXAMPLES = [{"id":"measure","title":"Measure","words":["measure","distance","how far","far"],"reply":"Measuring from there. Look at the second point and hold still, or say \"set\".","prompt":"Measure from that to wherever I look next","code":"// \"Measure from that to wherever I look next\"\n// Sensing only. The first point is whatever was at the centre of the view when you asked; the second follows\n// your gaze and locks when you hold still on something for a moment (or say \"set\").\nconst aim = () => space.raycast(user.head.position, user.head.forward, 12);\nconst first = (space.view && space.view.point(0.5, 0.5)) || aim();\nif (!first) {\n  const at = vec.add(user.head.position, vec.scale(user.head.forward, 1.2));\n  kit.appear(kit.pill('Look at something solid and ask again', { style: 'outline', position: at, billboard: 'full' }));\n  scene.after(3, finish);\n  return;\n}\n\nconst a = first.position;\nscene.sphere({ radius: 0.022, color: 'accent', shade: false, position: a });\nconst end = scene.sphere({ radius: 0.022, color: 'accent', shade: false, visible: false });\nlet line = null, tag = null, again = null;\nlet b = null, locked = false, steady = 0, steadyAt = null;\n\nfunction draw(to) {\n  b = to;\n  if (line) line.remove();\n  if (tag) tag.remove();\n  line = scene.line({ points: [a, to], width: locked ? 0.008 : 0.005, color: locked ? 'accent' : 'accentDeep' });\n  end.position = to;\n  end.visible = true;\n  const across = vec.length(vec.flat(vec.sub(to, a))), up = Math.abs(to[1] - a[1]);\n  const text = `${vec.distance(a, to).toFixed(2)} m` + (locked ? `  ·  across ${across.toFixed(2)}  ·  up ${up.toFixed(2)}` : '');\n  tag = kit.pill(text, { style: locked ? 'solid' : 'outline', position: vec.add(vec.lerp(a, to, 0.5), [0, 0.09, 0]), billboard: 'full' });\n}\n\nfunction lock() {\n  if (locked || !b) return;\n  locked = true;\n  draw(b);\n  again = kit.button('Measure again', () => { locked = false; steady = 0; again.remove(); again = null; }, { primary: false });\n  again.set({ position: vec.add(vec.lerp(a, b, 0.5), [0, 0.02, 0]), billboard: 'full' });\n}\n\n// Ten times a second is plenty for a line that follows the eyes.\nscene.every(0.1, () => {\n  if (locked) return;\n  const hit = aim();\n  if (!hit || vec.distance(hit.position, a) < 0.03) return;\n  if (steadyAt && vec.distance(hit.position, steadyAt) < 0.05) steady += 0.1;\n  else { steady = 0; steadyAt = hit.position; }\n  draw(hit.position);\n  if (steady >= 1.5) lock();\n});\nvoice.on(['set', 'mark', 'here', 'lock'], lock);\n"},{"id":"surfaces","title":"Surfaces","words":["surface","surfaces","found","scan","planes"],"reply":"Outlining each surface as the device finds it.","prompt":"Show me what you have found so far, and keep it up to date","code":"// \"Show me what you have found so far, and keep it up to date\"\n// Sensing only. Nothing was scanned beforehand: surfaces appear in space.surfaces() as the device finds them,\n// and this draws each one the moment it shows up.\nconst colours = { floor: 'accent', wall: 'accentDeep', table: 'success' };\nconst drawn = {};\nlet counter = null, count = 0;\n\nfunction show(s) {\n  const colour = colours[s.kind] || 'accent';\n  const w = s.size[0], wall = s.kind === 'wall';\n  const y = s.kind === 'table' ? s.size[1] / 2 + 0.012 : 0.012;\n  const corners = wall\n    ? [[-w / 2, -s.size[1] / 2, 0.02], [w / 2, -s.size[1] / 2, 0.02], [w / 2, s.size[1] / 2, 0.02], [-w / 2, s.size[1] / 2, 0.02]]\n    : [[-w / 2, y, -s.size[2] / 2], [w / 2, y, -s.size[2] / 2], [w / 2, y, s.size[2] / 2], [-w / 2, y, s.size[2] / 2]];\n  // Pull the outline in a hand's width so neighbouring surfaces do not share an edge.\n  const points = corners.map(c => vec.add(s.position, quat.rotate(s.rotation, c.map(v => v - Math.sign(v) * (Math.abs(v) > 0.2 ? 0.1 : 0)))));\n  points.push(points[0]);\n  scene.line({ points, width: 0.014, color: colour });\n\n  const area = wall ? w * s.size[1] : w * s.size[2];\n  const name = s.kind.charAt(0).toUpperCase() + s.kind.slice(1);\n  // Label it where the user was looking when it was found, snapped onto the surface.\n  const look = space.raycast(user.head.position, user.head.forward, 10);\n  let at = wall ? vec.add(s.position, quat.rotate(s.rotation, [0, 0.2, 0.03])) : vec.add(s.position, quat.rotate(s.rotation, [0, y, 0]));\n  if (look && !wall && s.kind === 'floor' && Math.abs(look.position[1] - s.position[1]) < 0.05) at = look.position;\n  kit.appear(kit.label(`${name}  ·  ${area.toFixed(1)} m²`, at, { color: colour, style: 'solid', stem: wall ? 0 : 0.5 }));\n}\n\nfunction scan() {\n  for (const s of space.surfaces()) {\n    if (drawn[s.id]) continue;\n    drawn[s.id] = true;\n    count++;\n    show(s);\n  }\n  // A running count that stays with the user.\n  const text = count === 0 ? 'Looking for surfaces...' : `${count} surface${count === 1 ? '' : 's'} found`;\n  if (!counter || counter.data.text !== text) {\n    if (counter) counter.remove();\n    counter = kit.pill(text, { style: 'outline', size: theme.text.small, billboard: 'full' });\n    counter.data.text = text;\n  }\n}\n\nscene.onFrame(() => {\n  if (!counter) return;\n  const head = user.head;\n  const flat = vec.normalize(vec.flat(head.forward));\n  const target = vec.add(vec.add(head.position, vec.scale(flat, 0.9)), [0, -0.32, 0]);\n  counter.position = vec.lerp(counter.position, target, 0.12);\n});\nscan();\nscene.every(0.4, scan);\n"},{"id":"keep-clear","title":"Keep-clear zone","words":["keep clear","keep-clear","safety","zone","circle","exclusion"],"reply":"Two metre zone on the floor in front of it.","prompt":"Put a two metre keep-clear zone on the floor in front of that","code":"// \"Put a two metre keep-clear zone on the floor in front of that\"\n// Sensing only. \"That\" is whatever was at the centre of the view; the zone sits on the floor in front of it\n// and reacts when the user steps inside.\nconst hit = (space.view && space.view.point(0.5, 0.5)) || space.raycast(user.head.position, user.head.forward, 12);\nif (!hit) {\n  const at = vec.add(user.head.position, vec.scale(user.head.forward, 1.2));\n  kit.appear(kit.pill('Look at the thing to keep clear of and ask again', { style: 'outline', position: at, billboard: 'full' }));\n  scene.after(3, finish);\n  return;\n}\n\nconst R = 1.0;\n// Step out from the surface that was hit, along the direction it faces. Looking at the floor itself gives a\n// vertical normal, in which case the zone is centred on that spot.\nconst out = vec.flat(hit.normal);\nconst centre = space.floorBelow(vec.length(out) > 0.3 ? vec.add(hit.position, vec.scale(vec.normalize(out), R + 0.05)) : hit.position);\nconst lift = h => vec.add(centre, [0, h, 0]);\n\nconst zone = scene.group({ position: lift(0) });\nconst fill = scene.disc({ parent: zone, radius: R, position: [0, 0.006, 0], color: 'warning', opacity: 0.14, shade: false });\nconst ring = scene.torus({ parent: zone, radius: R, tube: 0.014, position: [0, 0.014, 0], color: 'warning', shade: false });\n// Short posts at the compass points make the edge readable from a distance.\nfor (let i = 0; i < 8; i++) {\n  const a = i * Math.PI / 4;\n  scene.cylinder({ parent: zone, radius: 0.012, height: 0.22, position: [Math.cos(a) * R, 0.11, Math.sin(a) * R], color: 'warning' });\n}\nkit.appear(zone);\n\nconst edge = vec.add(centre, vec.scale(vec.normalize(vec.flat(vec.sub(user.head.position, centre))), R));\nconst calm = kit.label('Keep clear  ·  2 m', edge, { color: 'warning', style: 'outline', stem: 1.05 });\nconst alarm = kit.label('Step back', edge, { color: '#D92D20', style: 'solid', stem: 1.05 });\nalarm.visible = false;\n\nlet inside = false;\nscene.onFrame((dt, time) => {\n  const now = vec.length(vec.flat(vec.sub(user.head.position, centre))) < R;\n  if (now !== inside) {\n    inside = now;\n    ring.color = inside ? '#D92D20' : 'warning';\n    fill.color = inside ? '#D92D20' : 'warning';\n    calm.visible = !inside;\n    alarm.visible = inside;\n  }\n  fill.opacity = inside ? 0.22 + 0.12 * Math.sin(time * 8) : 0.14;\n});\n"},{"id":"route","title":"Route","words":["route","guide","way","take me","navigate","path"],"reply":"Follow the trail.","prompt":"Guide me to that","code":"// \"Guide me to that\"\n// Sensing only. The goal is the floor in front of whatever was at the centre of the view. The path is checked\n// with rays at shin and waist height and bends around anything in the way; it is re-planned as the user walks.\nconst hit = (space.view && space.view.point(0.5, 0.5)) || space.raycast(user.head.position, user.head.forward, 12);\nif (!hit) {\n  const at = vec.add(user.head.position, vec.scale(user.head.forward, 1.2));\n  kit.appear(kit.pill('Look at where you want to go and ask again', { style: 'outline', position: at, billboard: 'full' }));\n  scene.after(3, finish);\n  return;\n}\n\nconst out = vec.flat(hit.normal);\nconst goal = space.floorBelow(vec.length(out) > 0.3 ? vec.add(hit.position, vec.scale(vec.normalize(out), 0.45)) : hit.position);\nconst feet = () => [user.head.position[0], space.floorY, user.head.position[2]];\n\nfunction clear(from, to) {\n  const d = vec.sub(to, from), length = vec.length(d);\n  if (length < 0.05) return true;\n  for (const h of [0.25, 0.9]) {\n    const blocked = space.raycast([from[0], from[1] + h, from[2]], d, length);\n    if (blocked && blocked.distance < length - 0.2) return false;\n  }\n  return true;\n}\n\nfunction plan(from) {\n  if (clear(from, goal)) return [from, goal];\n  const dir = vec.normalize(vec.sub(goal, from)), side = [dir[2], 0, -dir[0]], length = vec.distance(from, goal);\n  for (const along of [0.5, 0.35, 0.65]) {\n    for (const off of [0.8, -0.8, 1.5, -1.5, 2.3, -2.3]) {\n      const via = vec.add(vec.add(from, vec.scale(dir, length * along)), vec.scale(side, off));\n      if (clear(from, via) && clear(via, goal)) return [from, via, goal];\n    }\n  }\n  return [from, goal];\n}\n\n// The destination: a ring that breathes, and how far there is left to walk.\nconst ring = scene.torus({ radius: 0.28, tube: 0.014, position: vec.add(goal, [0, 0.014, 0]), color: 'accent', shade: false });\nscene.disc({ radius: 0.28, position: vec.add(goal, [0, 0.006, 0]), color: 'accent', opacity: 0.16, shade: false });\nscene.onFrame((dt, time) => ring.scale = 1 + 0.08 * Math.sin(time * 3));\n\nlet path = null, tag = null, arrived = false;\nfunction update() {\n  if (arrived) return;\n  const from = feet(), points = plan(from);\n  let left = 0;\n  for (let i = 0; i < points.length - 1; i++) left += vec.distance(points[i], points[i + 1]);\n  if (path) path.remove();\n  if (tag) tag.remove();\n  if (left < 0.6) {\n    arrived = true;\n    tag = kit.label('You have arrived', goal, { style: 'solid', stem: 1.1 });\n    scene.after(2.5, finish);\n    return;\n  }\n  // Start the trail a step ahead of the user's feet so it does not sit under them.\n  const ahead = vec.add(from, vec.scale(vec.normalize(vec.sub(points[1], from)), Math.min(0.5, left * 0.2)));\n  path = scene.tube({ points: [ahead, ...points.slice(1)].map(p => vec.add(p, [0, 0.03, 0])), radius: 0.03, color: 'accent', opacity: 0.9, flow: { speed: 0.7, density: 5 } });\n  tag = kit.label(`${left.toFixed(1)} m`, goal, { style: 'outline', stem: 1.1 });\n}\nupdate();\nscene.every(0.5, update);\n"},{"id":"height","title":"Height","words":["height","high","tall"],"reply":"Measured from the floor.","prompt":"How high is that?","code":"// \"How high is that?\"\n// Sensing only. A ruler from the floor straight up to whatever was at the centre of the view.\nconst hit = (space.view && space.view.point(0.5, 0.5)) || space.raycast(user.head.position, user.head.forward, 12);\nif (!hit) {\n  const at = vec.add(user.head.position, vec.scale(user.head.forward, 1.2));\n  kit.appear(kit.pill('Look at the thing to measure and ask again', { style: 'outline', position: at, billboard: 'full' }));\n  scene.after(3, finish);\n  return;\n}\n\n// Stand the ruler just proud of the surface so it is not buried in it.\nconst top = vec.add(hit.position, vec.scale(hit.normal, 0.03));\nconst base = [top[0], space.floorY, top[2]];\nconst height = top[1] - base[1];\nconst ruler = scene.group({ position: base, rotation: space.faceUser(base) });\n\nscene.line({ parent: ruler, points: [[0, 0, 0], [0, height, 0]], width: 0.008, color: 'accent' });\n// A tick every ten centimetres, longer and numbered every half metre.\nfor (let cm = 0; cm <= Math.floor(height * 10) * 10; cm += 10) {\n  const major = cm % 50 === 0, y = cm / 100, w = major ? 0.07 : 0.035;\n  scene.line({ parent: ruler, points: [[0, y, 0], [w, y, 0]], width: major ? 0.005 : 0.003, color: 'accent' });\n  if (major && cm > 0) scene.text({ parent: ruler, text: (cm / 100).toFixed(1), size: theme.text.small, color: 'accentDeep', position: [w + 0.015, y, 0] });\n}\nscene.line({ parent: ruler, points: [[-0.06, height, 0], [0.1, height, 0]], width: 0.006, color: 'accent' });\nscene.sphere({ radius: 0.016, position: hit.position, color: 'accent', shade: false });\n\nconst tag = kit.pill(`${height.toFixed(2)} m`, { style: 'solid', position: vec.add(top, [0, 0.07, 0]), billboard: 'full' });\nkit.appear(tag);\n\n// Which is taller, this or the user? A small, live comparison.\nconst note = scene.text({ text: '', size: theme.text.small, color: 'muted', align: 'center', position: vec.add(top, [0, 0.13, 0]), billboard: 'full' });\nscene.every(0.5, () => {\n  const d = user.head.position[1] - space.floorY - height;\n  note.text = Math.abs(d) < 0.05 ? 'level with your eyes' : `${Math.abs(d).toFixed(2)} m ${d > 0 ? 'below' : 'above'} your eye line`;\n});\n"}];
